remediation.scriptTemplate:
$ruleId = 'a8f5898e-1dc8-49a9-9878-85004b8a61e6'
$preferences = Get-MpPreference
$index = [Array]::IndexOf($preferences.AttackSurfaceReductionRules_Ids, $ruleId)
if ($index -lt 0) {
    'ASR rule is not configured.'
} else {
    [pscustomobject]@{
        RuleId = $ruleId
        Action = $preferences.AttackSurfaceReductionRules_Actions[$index]
    }
}

